import React from 'react';

const Category = ({ 
  categories, 
  categoryInput, 
  setCategoryInput, 
  handleAddCategory, 
  handleDeleteCategory,
  criteria = [] // Add criteria prop with default empty array
}) => {
  return (
    <section className="section">
      <h2>Adding Category</h2>
      <div className="table-container">
        <table className="data-table">
          <thead>
            <tr>
              <th>No.</th>
              <th>Name</th>
              <th>Criteria Count</th>
              <th>Action</th>
            </tr>
          </thead>
          <tbody>
            {categories.map((category, index) => {
              // Count criteria for this category
              const criteriaCount = criteria.filter(crit => crit.category_id === category.id || crit.category_name === category.name).length;

              return (
                <tr key={category.id}>
                  <td>{index + 1}</td>
                  <td>{category.name}</td>
                  <td>
                    <span className="criteria-count">
                      {criteriaCount} {criteriaCount === 1 ? 'criteria' : 'criterias'}
                    </span>
                  </td>
                  <td>
                    <button 
                      className="action-btn edit-btn" 
                      title="Edit" 
                      disabled
                    >
                      <i className="fi fi-rr-edit"></i>
                    </button>
                    <button 
                      className="action-btn delete-btn" 
                      onClick={() => handleDeleteCategory(category.id)} 
                      title="Delete"
                    >
                      <i className="fi fi-rr-trash"></i>
                    </button>
                  </td>
                </tr>
              );
            })}
          </tbody>
        </table>
      </div>
      <div className="input-group">
        <input
          type="text"
          placeholder="Enter category name"
          value={categoryInput}
          onChange={(e) => setCategoryInput(e.target.value)}
          onKeyPress={(e) => e.key === 'Enter' && handleAddCategory()}
        />
        <button className="submit-btn" onClick={handleAddCategory}>Submit</button>
      </div>
    </section>
  );
};

export default Category;
